begin;
do $test$
declare c public.conductores; otro public.conductores; h bigint; r1 bigint; r2 bigint; r3 bigint; result jsonb; blocked boolean; fecha_prueba date:=current_date+600; ausencias bigint;
begin
 select * into c from public.conductores where activo and usuario_id is not null and not exists(select 1 from public.administradores a where a.usuario_id=conductores.usuario_id) and not exists(select 1 from r200_privado.operadores_mantenimiento m where m.usuario_id=conductores.usuario_id) order by id limit 1;
 select * into otro from public.conductores where activo and usuario_id is not null and usuario_id<>c.usuario_id and not exists(select 1 from public.administradores a where a.usuario_id=conductores.usuario_id) order by id limit 1;
 if c.id is null or otro.id is null then raise exception 'Se necesitan dos conductores activos';end if;
 select count(*) into ausencias from public.historial_ausencias;
 perform set_config('request.jwt.claim.sub',c.usuario_id::text,true);
 result:=public.r200_publicar_viaje(c.id,fecha_prueba,'04:00','Tepic',4,'Prueba transaccional sin guardar');h:=(result->>'id')::bigint;
 insert into public.reservaciones(horario_id,nombre_pasajero,telefono_pasajero,asientos) values(h,'Prueba A','0000000000',2) returning id into r1;
 insert into public.reservaciones(horario_id,nombre_pasajero,telefono_pasajero,asientos) values(h,'Prueba B','0000000001',1) returning id into r2;
 insert into public.reservaciones(horario_id,nombre_pasajero,telefono_pasajero,asientos) values(h,'Prueba C','0000000002',1) returning id into r3;
 perform set_config('request.jwt.claim.sub',otro.usuario_id::text,true);
 blocked:=false;begin perform public.r200_cancelar_reserva_conductor(r1,'Prueba ajena');exception when others then blocked:=sqlerrm like '%Acceso no autorizado%';end;if not blocked then raise exception 'Permitió reserva ajena';end if;
 blocked:=false;begin perform public.r200_cancelar_viaje(h,'Prueba ajena');exception when others then blocked:=sqlerrm like '%Acceso no autorizado%';end;if not blocked then raise exception 'Permitió viaje ajeno';end if;
 perform set_config('request.jwt.claim.sub','',true);
 blocked:=false;begin perform public.r200_cancelar_viaje(h,'Prueba anónima');exception when others then blocked:=sqlerrm like '%Acceso no autorizado%';end;if not blocked then raise exception 'Permitió anónimo';end if;
 perform set_config('request.jwt.claim.sub',c.usuario_id::text,true);
 blocked:=false;begin perform public.r200_cancelar_viaje(h,'');exception when others then blocked:=sqlerrm like '%motivo%';end;if not blocked then raise exception 'Permitió sin motivo';end if;
 result:=public.r200_cancelar_reserva_conductor(r1,'Cancelación de prueba');
 if result->>'estado'<>'cancelada' or result->>'motivo_cancelacion'<>'Cancelación de prueba' or not(result->>'cancelada_por_conductor')::boolean then raise exception 'Boleto individual incorrecto';end if;
 if (select cupos_ocupados from public.horarios where id=h)<>2 then raise exception 'No liberó dos cupos';end if;
 perform public.r200_cancelar_reserva_conductor(r1,'Reintento de prueba');if (select cupos_ocupados from public.horarios where id=h)<>2 then raise exception 'Reintento duplicó liberación';end if;
 update public.horarios set fecha=current_date-1 where id=h;
 blocked:=false;begin perform public.r200_cancelar_reserva_conductor(r2,'Salida pasada');exception when others then blocked:=sqlerrm like '%antes de la salida%';end;if not blocked then raise exception 'Permitió reserva pasada';end if;
 blocked:=false;begin perform public.r200_cancelar_viaje(h,'Salida pasada');exception when others then blocked:=sqlerrm like '%antes de su salida%';end;if not blocked then raise exception 'Permitió viaje pasado';end if;
 update public.horarios set fecha=fecha_prueba where id=h;
 result:=public.r200_cancelar_viaje(h,'Prueba viaje completo');
 if (result->>'reservas_canceladas')::integer<>2 then raise exception 'No canceló ambas reservas';end if;
 if exists(select 1 from public.horarios where id=h and (activo or cupos_ocupados<>0 or cancelado_at is null)) then raise exception 'No cerró viaje y liberó cupos';end if;
 if exists(select 1 from public.reservaciones where horario_id=h and estado<>'cancelada') then raise exception 'Quedaron boletos confirmados';end if;
 if not(public.r200_ticket_interno(r2)->>'viaje_cancelado')::boolean then raise exception 'Boleto no informa viaje cancelado';end if;
 if not(public.r200_cancelar_viaje(h,'Reintento completo')->>'ya_cancelado')::boolean then raise exception 'Reintento de viaje no idempotente';end if;
 result:=public.r200_publicar_viaje(c.id,fecha_prueba,'04:00','Tepic',4,'Nueva salida tras cancelar');if (result->>'id')::bigint=h or exists(select 1 from public.horarios where id=h and activo) then raise exception 'Reabrió el viaje cancelado';end if;
 if (select count(*) from public.historial_ausencias)<>ausencias then raise exception 'Creó ausencia por cancelación';end if;
 if has_function_privilege('anon','public.r200_cancelar_viaje(bigint,text)','execute') or has_function_privilege('anon','public.r200_cancelar_reserva_conductor(bigint,text)','execute') then raise exception 'Permisos anónimos indebidos';end if;
end $test$;
rollback;
select 'Cancelaciones, cupos, boletos, motivos, reintentos, fechas y permisos verificados; pruebas revertidas' as resultado;
